<?php declare(strict_types=1); ?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kategoriler</title><style>body{font-family:system-ui;background:#f5f7f5;color:#26332b;margin:0}.wrap{max-width:1000px;margin:35px auto;padding:0 18px}.panel{background:white;padding:22px;border-radius:14px;margin:15px 0}input,textarea{padding:10px;border:1px solid #dfe6e0;border-radius:8px;margin:5px;font:inherit}button{background:#176b50;color:white;border:0;padding:10px 14px;border-radius:8px;font-weight:700}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:12px;border-bottom:1px solid #edf0ed}</style></head><body><main class="wrap"><h1>Konaklama kategorileri</h1><section class="panel"><h2>Yeni kategori</h2><form method="post" action="/admin/categories/save"><?= csrf_field() ?><input name="name" placeholder="Kategori adı" required><input name="slug" placeholder="url-kisa-adi" required><input name="description" placeholder="Açıklama"><input name="sort_order" type="number" value="10" style="width:80px"><button>Ekle</button></form></section><section class="panel"><table><thead><tr><th>Kategori</th><th>URL</th><th>Açıklama</th><th>Durum</th><th></th></tr></thead><tbody><?php foreach($categories as $category): ?><tr><td><?= e($category['name']) ?></td><td><?= e($category['slug']) ?></td><td><?= e($category['description']) ?></td><td><?= (int)$category['is_active']?'Aktif':'Pasif' ?></td><td><form method="post" action="/admin/categories/delete"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$category['id'] ?>"><button style="background:#a43">Sil</button></form></td></tr><?php endforeach; ?></tbody></table></section><p><a href="/admin">Yönetim paneli</a></p></main></body></html>